import {pickTile,expandRaft,addPlant,setPointer,resizeScene,setSceneSettings} from './scene.js';
const $=s=>document.querySelector(s);
const state={hunger:62,thirst:35,hull:78,sanity:55,ap:3,day:1,selected:null,used:[],nets:0,food:2,planted:0,expanded:false};window.gameState=state;
const preferences={motion:!matchMedia('(prefers-reduced-motion: reduce)').matches,quality:'high'};setSceneSettings(preferences);
const cards=[{id:'net',cost:1,title:'制作渔网',desc:'合成获得渔网<br>可以定期获取食物。',type:'合成',x:307,y:646,craft:true},{id:'expand',cost:2,title:'扩大木筏',desc:'在木筏右侧增加1格<br>可放置更多建筑。',type:'建造',x:524,y:646,craft:true},{id:'repair',cost:1,title:'修理船体',desc:'恢复30点船体耐久。',type:'生存',x:738,y:646},{id:'plant',cost:2,title:'种植海藻',desc:'获得2份食物，<br>之后每回合+1食物。',type:'生存',x:953,y:646},{id:'fish',cost:1,title:'食用鱼肉',desc:'恢复40点饥饿。',type:'食物',x:1170,y:646}];
const icons={hunger:'<path d="M5 3v11M9 3v11M13 3v11M5 11q4 7 8 0M9 16v16M24 3q-8 8-2 16h3V3M24 19v13"/>',thirst:'<path d="M16 2Q4 16 4 23a12 12 0 0024 0Q28 16 16 2"/>',hull:'<path d="M2 22h29l-6 10H8zM15 4v18M16 6h10l-3 8H16M8 15h7v7H8z"/>',sanity:'<path d="M8 9Q7 3 13 3Q19 0 22 7Q30 4 30 12Q36 15 29 20Q27 26 21 24L23 32h-7l-2-9Q6 26 6 19Q-1 17 3 12Q4 9 8 9z"/>'};
const stats=[['hunger','饥饿','#ff6534','#ffb260'],['thirst','口渴','#2e9dc2','#62cbe4'],['hull','船体','#98a8b2','#e7e5df'],['sanity','理智','#703dc5','#c46ef5']];
function renderStats(){ $('#stats').innerHTML=stats.map(([id,name,color,light])=>`<div class="stat"><svg viewBox="0 0 36 36">${icons[id]}</svg><b>${name}</b><div class="stat-track"><div class="stat-fill" style="--color:${color};--light:${light};width:${state[id]}%"></div></div><em>${state[id]}/100</em></div>`).join('');$('#ap').textContent=`${state.ap}/3`;[...$('#ap-lights').children].forEach((e,i)=>e.classList.toggle('spent',i>=state.ap));$('#day').textContent=String(state.day).padStart(2,'0')}
function renderHand(){ $('#hand').innerHTML=cards.map(c=>`<button class="card ${c.craft?'crafting-card':''} ${state.selected===c.id?'selected':''} ${state.used.includes(c.id)?'used':''}" data-card="${c.id}" aria-pressed="${state.selected===c.id}" aria-label="${c.title}，消耗${c.cost}行动点"><span class="card-cost">${c.cost}</span><div class="card-art" style="background-position:-${c.x}px -${c.y}px"></div><h3>${c.title}</h3><p>${c.desc}</p><span class="card-type">${c.type}</span></button>`).join('');$('#craft').classList.toggle('active',!!state.selected);$('#craft-text').textContent=state.selected?`${cards.find(c=>c.id===state.selected).title} · 点击使用`:'将卡牌放入此处合成';$('#raft-hint').textContent=state.selected?'点击木筏或合成位置使用卡牌':'选择卡牌 · 在木筏上建造'}
let toastTimer;function toast(msg){clearTimeout(toastTimer);$('#toast').textContent=msg;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3100)}
function selectCard(id){const c=cards.find(c=>c.id===id);if(state.used.includes(id))return toast('这张卡牌已使用，下个回合重新获得。');if(c.cost>state.ap)return toast('行动点不足，请结束回合。');state.selected=state.selected===id?null:id;renderHand()}
function useCard(tile){if(!state.selected)return toast('先选择一张手牌。');const c=cards.find(c=>c.id===state.selected);if(c.cost>state.ap)return toast('行动点不足。');if(c.id==='expand'&&state.expanded)return toast('木筏已扩建，继续探索以获取更多木材。');state.ap-=c.cost;state.used.push(c.id);state.selected=null;let msg='';switch(c.id){case'net':state.nets++;msg='渔网制作完成 · 每回合获得1份食物';break;case'expand':expandRaft();state.expanded=true;msg='木筏扩建完成 · 新增1格可用位置';break;case'repair':state.hull=Math.min(100,state.hull+30);msg='船体修理完成 · 耐久恢复30点';break;case'plant':state.food+=2;state.planted++;addPlant(tile?.x??1.1,tile?.z??2.25);msg='海藻种植完成 · 获得2份食物';break;case'fish':state.hunger=Math.min(100,state.hunger+40);state.food=Math.max(0,state.food-1);msg='食用鱼肉 · 饥饿恢复40点';break}renderStats();renderHand();toast(msg)}
function nextTurn(){state.day++;state.ap=3;state.used=[];state.selected=null;state.food+=state.nets+state.planted;state.hunger=Math.max(0,state.hunger-8);state.thirst=Math.max(0,state.thirst-6);state.hull=Math.max(0,state.hull-3);state.sanity=Math.max(0,state.sanity-2);renderStats();renderHand();toast(`第${state.day}天 · 行动点已恢复${state.nets+state.planted?`，获得${state.nets+state.planted}份食物`:''}`)}
$('#hand').addEventListener('click',e=>{const b=e.target.closest('[data-card]');if(b)selectCard(b.dataset.card)});$('#craft').addEventListener('click',()=>useCard());$('#organize').addEventListener('click',()=>{cards.sort((a,b)=>a.cost-b.cost||a.title.localeCompare(b.title,'zh-CN'));renderHand();toast('手牌已按行动点消耗整理。')});$('#end-turn').addEventListener('click',nextTurn);
let scenePointer={x:0,y:0};$('#world').addEventListener('pointermove',e=>{const b=$('#game').getBoundingClientRect();scenePointer={x:((e.clientX-b.left)/b.width)*2-1,y:-((e.clientY-b.top)/b.height)*2+1};setPointer(scenePointer.x,scenePointer.y);pickTile(scenePointer.x,scenePointer.y)});$('#world').addEventListener('click',()=>{const tile=pickTile(scenePointer.x,scenePointer.y);if(tile&&state.selected)useCard(tile)});
const panel=$('#panel');function showPanel(html){$('#panel-content').innerHTML=html;panel.showModal()}function closePanel(){panel.close()}$('#close-panel').addEventListener('click',closePanel);panel.addEventListener('click',e=>{if(e.target===panel)closePanel()});
function openPanel(type){switch(type){case'map':showPanel(`<h2>航行图</h2><p>未知的海域，遗忘的文明。选择下一处停靠点。</p><div class="dialog-grid"><div class="dialog-item"><strong>◇ 沉没的城市</strong><span>文明遗迹 · 搜寻物资</span><button data-go="city">前往城市</button></div><div class="dialog-item"><strong>◇ 神秘岛屿</strong><span>迷雾海岛 · 补充饮水</span><button data-go="island">前往岛屿</button></div></div>`);break;case'inventory':showPanel(`<h2>藏品</h2><div class="dialog-grid"><div class="dialog-item"><strong>食物</strong><span>${state.food} 份 · 维持航行</span></div><div class="dialog-item"><strong>渔网</strong><span>${state.nets} 张 · 自动捕鱼</span></div><div class="dialog-item"><strong>海藻田</strong><span>${state.planted} 处 · 持续产出</span></div><div class="dialog-item"><strong>木筏</strong><span>${state.expanded?13:12} 格 · 耐久 ${state.hull}/100</span></div></div>`);break;case'deck':showPanel(`<h2>牌库</h2><p>每回合获得3点行动点，手牌在新回合恢复。</p>${cards.map(c=>`<div class="setting"><span>${c.title}</span><span>${c.cost} 行动点 · ${c.type}${state.used.includes(c.id)?' · 已使用':''}</span></div>`).join('')}`);break;case'settings':showPanel(`<h2>设置</h2><label class="setting">动态海面与漂浮<input id="motion-setting" type="checkbox" checked></label><label class="setting">高画质<input id="quality-setting" type="checkbox" checked></label><p>点击手牌选择，再点击木筏或合成位置使用。<br>按 Esc 取消选择，按 Enter 结束回合。</p><button id="reset-game">重新开始航行</button>`);break}}
document.querySelectorAll('[data-panel]').forEach(b=>b.addEventListener('click',()=>openPanel(b.dataset.panel)));
function travel(where){showPanel(`<h2>${where==='city'?'沉没的城市':'神秘岛屿'}</h2><p>${where==='city'?'残破的高塔沉入海底，昔日的钟声仍在暗流中回荡。你发现一只密封的物资箱。':'穿过迷雾，一座无人岛出现在眼前。岩缝中的淡水足够补充你的储备。'}</p><button data-confirm-travel="${where}">消耗1行动点 · 探索</button>`)}
document.querySelectorAll('[data-travel]').forEach(b=>b.addEventListener('click',()=>travel(b.dataset.travel)));
$('#vortex-button').addEventListener('click',()=>showPanel('<h2>涌泉</h2><h3>深渊正在注视着你……</h3><p>赤红的潮汐在黑色岩柱之间旋转。<br>靠近这片水域会消耗你的理智，航行时请保持警惕。</p><button id="vortex-investigate">凝视深渊 · 消耗1行动点</button>'));
panel.addEventListener('click',e=>{const go=e.target.closest('[data-go]');if(go){closePanel();travel(go.dataset.go)}const t=e.target.closest('[data-confirm-travel]');if(t){if(state.ap<1)return toast('行动点不足，请结束回合。');state.ap--;if(t.dataset.confirmTravel==='city'){state.food+=3;state.sanity=Math.max(0,state.sanity-5);toast('发现物资箱 · 食物+3，理智−5')}else{state.thirst=Math.min(100,state.thirst+35);toast('补充淡水 · 口渴恢复35点')}renderStats();closePanel()}if(e.target.id==='vortex-investigate'){if(state.ap<1)return toast('行动点不足，请结束回合。');state.ap--;state.sanity=Math.max(0,state.sanity-15);state.food+=2;renderStats();closePanel();toast('深渊回响 · 理智−15，获得2份食物')}if(e.target.id==='reset-game')location.reload()});
panel.addEventListener('change',e=>{if(e.target.id==='motion-setting')preferences.motion=e.target.checked;if(e.target.id==='quality-setting')preferences.quality=e.target.checked?'high':'low';setSceneSettings(preferences)});
panel.addEventListener('close',()=>$('#raft-hint').focus());
document.querySelector('[data-panel="settings"]').addEventListener('click',()=>{$('#motion-setting').checked=preferences.motion;$('#quality-setting').checked=preferences.quality==='high'});
document.addEventListener('keydown',e=>{if(panel.open)return;if(e.key==='Escape'){state.selected=null;renderHand()}if(e.key==='Enter'){e.preventDefault();nextTurn()}if(['1','2','3','4','5'].includes(e.key))selectCard(cards[Number(e.key)-1].id)});
function resize(){const scale=Math.min(innerWidth/1672,innerHeight/941);$('#game').style.transform=`scale(${scale})`;resizeScene(Math.round(1672*scale),Math.round(941*scale))}addEventListener('resize',resize);renderStats();renderHand();resize();requestAnimationFrame(()=>{$('#loading').classList.add('done');setTimeout(()=>$('#loading').remove(),750)});
window.addEventListener('scene-error',e=>toast(e.detail));
// Expose the same game actions when the browser supports the WebMCP API.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const empty={type:'object',properties:{},additionalProperties:false};const tools=[{name:'read_voyage',description:'读取本地演示游戏的生存数值、行动点和手牌状态。',inputSchema:empty,annotations:{readOnlyHint:true},execute:()=>({...state,used:[...state.used]})},{name:'play_survival_card',description:'在本地演示游戏中使用一张手牌，消耗行动点并更新生存数值或三维木筏。',inputSchema:{type:'object',properties:{cardId:{type:'string',enum:['net','expand','repair','plant','fish']}},required:['cardId'],additionalProperties:false},execute:input=>{if(!input||typeof input!=='object'||Object.keys(input).some(k=>k!=='cardId'))throw new Error('参数无效');const card=cards.find(c=>c.id===input.cardId);if(!card)throw new Error('未知卡牌');if(state.used.includes(card.id))throw new Error('卡牌本回合已使用');if(state.ap<card.cost)throw new Error('行动点不足');if(card.id==='expand'&&state.expanded)throw new Error('木筏已扩建');state.selected=card.id;useCard();return {...state,used:[...state.used]}}},{name:'end_survival_turn',description:'结束本地演示游戏的当前回合，恢复行动点并推进一天。',inputSchema:empty,execute:input=>{if(input&&Object.keys(input).length)throw new Error('无需参数');nextTurn();return{day:state.day,ap:state.ap,food:state.food}}}];for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
